{
	disable Send_Invoice;
	disable Cancel_Invoice;
	disable Fiscal_Document_Number;
}
disable Sent_By;

if(input.Cancel_Invoice == true)
{
	show Reason_Why_Cancelled;
}
else
{
	hide Reason_Why_Cancelled;
	input.Reason_Why_Cancelled = "";
}

if(input.Company != null)
{
	input.Display_Name_Company = input.Company.Company_Name;
}
else
{
	input.Display_Name_Company = "";
}

if(input.Main_Customer != null)
{
	input.Display_Name_Customer = input.Main_Customer.Party_Name + " - " + input.Main_Customer.Party_ID;
}
else
{
	input.Display_Name_Customer = "";
}

if(input.Discount_Amount == null)
{
	input.Discount_Amount = 0;
}
if(input.Discount_Amount > ifnull(input.Sub_Total,0))
{
	alert "Discount Amount cannot be greater than Sub Total.";
	input.Discount_Amount = ifnull(input.Sub_Total,0);
}
input.Grand_Total = ifnull(input.Sub_Total,0) + ifnull(input.Tax_Amount,0) - ifnull(input.Discount_Amount,0);
input.Balance_Due = ifnull(input.Grand_Total,0) - ifnull(input.Amount_Paid,0);

if(input.Discount_Percentage == null)
{
	input.Discount_Percentage = 0;
}
if(input.Discount_Percentage > 100)
{
	alert "Discount Percentage cannot be greater than 100%.";
	input.Discount_Percentage = 100;
}
discount_amt = ifnull(input.Sub_Total,0) * ifnull(input.Discount_Percentage,0) / 100;
input.Discount_Amount = discount_amt;
input.Grand_Total = ifnull(input.Sub_Total,0) + ifnull(input.Tax_Amount,0) - discount_amt;
input.Balance_Due = ifnull(input.Grand_Total,0) - ifnull(input.Amount_Paid,0);

if(input.Discount_Type == "None")
{
	hide Discount_Percentage;
	hide Discount_Amount;
	input.Discount_Percentage = 0;
	input.Discount_Amount = 0;
}
else if(input.Discount_Type == "Percentage")
{
	show Discount_Percentage;
	hide Discount_Amount;
	input.Discount_Amount = 0;
}
else if(input.Discount_Type == "Amount")
{
	hide Discount_Percentage;
	show Discount_Amount;
	input.Discount_Percentage = 0;
}

if(input.Send_Invoice == true)
{
	show Fiscal_Document_Number;
	show Date_Sent;
}
else
{
	hide Fiscal_Document_Number;
	hide Date_Sent;
	input.Fiscal_Document_Number = "";
	input.Date_Sent = null;
}

if(row.Service != null)
{
	row.Display_Name_Service=row.Service.Service_Name;
}
else
{
	row.Display_Name_Service="";
}

sub_total = ifnull(input.Sub_Total,0.0);
discount = ifnull(input.Discount_Amount,0.0);
grand_total = sub_total - discount + ifnull(input.Tax_Amount,0.0);
input.Grand_Total = grand_total;
input.Balance_Due = grand_total - ifnull(input.Amount_Paid,0.0);

if(input.Invoice_Number != null && input.Invoice_Number != "")
{
	row.Display_Name_Invoice=input.Invoice_Number;
}
// ==============================
// RECALCULATE INVOICE TOTALS
// ==============================
sub_total = 0.0;
for each  d in input.Details
{
	sub_total = sub_total + ifnull(d.Line_Total,0.0);
}
for each  s in input.Services
{
	sub_total = sub_total + ifnull(s.Line_Total,0.0);
}
input.Sub_Total = sub_total;
discount_amt = ifnull(input.Discount_Amount,0.0);
if(input.Discount_Type == "Percentage")
{
	discount_amt = sub_total * ifnull(input.Discount_Percentage,0.0) / 100;
	input.Discount_Amount = discount_amt;
}
tax_amt = ifnull(input.Tax_Amount,0.0);
grand_total = sub_total - discount_amt + tax_amt;
if(grand_total < 0)
{
	grand_total = 0;
}
input.Grand_Total = grand_total;
input.Balance_Due = grand_total - ifnull(input.Amount_Paid,0.0);
if(input.Balance_Due < 0)
{
	input.Balance_Due = 0;
}

// ==============================
// RECALCULATE INVOICE TOTALS
// ==============================
sub_total = 0.0;
for each  d in input.Details
{
	sub_total = sub_total + ifnull(d.Line_Total,0.0);
}
for each  s in input.Services
{
	sub_total = sub_total + ifnull(s.Line_Total,0.0);
}
input.Sub_Total = sub_total;
discount_amt = ifnull(input.Discount_Amount,0.0);
if(input.Discount_Type == "Percentage")
{
	discount_amt = sub_total * ifnull(input.Discount_Percentage,0.0) / 100;
	input.Discount_Amount = discount_amt;
}
tax_amt = ifnull(input.Tax_Amount,0.0);
grand_total = sub_total - discount_amt + tax_amt;
if(grand_total < 0)
{
	grand_total = 0;
}
input.Grand_Total = grand_total;
input.Balance_Due = grand_total - ifnull(input.Amount_Paid,0.0);
if(input.Balance_Due < 0)
{
	input.Balance_Due = 0;
}

if(input.Company == null || input.Invoice_Date == null || input.Customer == null)
{
	alert "Company, Invoice Date and Customer are required.";
	cancel submit;
}
if(ifnull(input.Invoice_Number,"").trim() == "" || input.Invoice_Number == "DOCUMENT_KEY_NOT_FOUND" || input.Invoice_Number == "LIMIT_REACHED")
{
	docKey = Document_Key[Voucher_Type == "Invoice" && Document_Key_Status == "Active"];
	if(docKey.ID == null)
	{
		alert "No active Invoice Document Key is configured.";
		cancel submit;
	}
	vno = thisapp.Generate_Voucher_Number(docKey.ID);
	if(vno == null || vno == "" || vno == "LIMIT_REACHED")
	{
		alert "Unable to generate Invoice Number. Check the Invoice Document Key.";
		cancel submit;
	}
	input.Invoice_Number = vno;
}
previous = Invoice[ID == input.ID];
if(previous.ID != null)
{
	if(ifnull(previous.Invoice_Number,"").trim() != "" && previous.Invoice_Number != "DOCUMENT_KEY_NOT_FOUND" && previous.Invoice_Number != "LIMIT_REACHED")
	{
		input.Invoice_Number = previous.Invoice_Number;
	}
	if(previous.Send_Invoice == true || previous.Invoice_Status == "Invoiced")
	{
		alert "This invoice has been sent and is locked. Use a controlled correction.";
		cancel submit;
	}
	if(previous.Customer != input.Customer && Invoice_Details[Invoice == input.ID].count() > 0)
	{
		alert "An invoice with linked details cannot change customer.";
		cancel submit;
	}
}
if(input.Send_Invoice == true && input.Cancel_Invoice == true)
{
	alert "An invoice cannot be sent and cancelled together.";
	cancel submit;
}
if(input.Send_Invoice == true)
{
	if(ifnull(input.Fiscal_Document_Number,"").trim() == "")
	{
		alert "Customer Invoice Number is required when sending the invoice.";
		cancel submit;
	}
	if(Invoice_Details[Invoice == input.ID && Invoice_Details_Status != "Cancelled"].count() == 0)
	{
		alert "Attach credited Sales Voucher details before sending.";
		cancel submit;
	}
	if(Invoice[Fiscal_Document_Number == input.Fiscal_Document_Number && ID != input.ID && Cancel_Invoice != true].count() > 0)
	{
		alert "Customer Invoice Number is already used.";
		cancel submit;
	}
}
if(input.Cancel_Invoice == true && ifnull(input.Reason_Why_Cancelled,"").trim() == "")
{
	alert "A cancellation reason is required.";
	cancel submit;
}
if(input.ID != null && input.ID > 0)
{
	for each  d in Invoice_Details[Invoice == input.ID && Invoice_Details_Status != "Cancelled"]
	{
		sv = Sales_Voucher[ID == d.Sales_Voucher1];
		if(sv.ID == null || sv.Customer != input.Customer || ifnull(sv.Amount_Credited,0) <= 0 || sv.Cancel_Voucher == true)
		{
			alert "All invoice details must be credited Sales Vouchers for the selected customer.";
			cancel submit;
		}
	}
	expected_ids = Invoice_Details[Invoice == input.ID].ID.getAll();
	actual_count = 0;
	for each  row in input.Details
	{
		actual_count = actual_count + 1;
		stored_line = Invoice_Details[ID == row.ID];
		if(!expected_ids.contains(row.ID) || stored_line.Sales_Voucher1 != row.Sales_Voucher1 || ifnull(stored_line.Rate,0) != ifnull(row.Rate,0) || ifnull(row.Quantity,0) != 1 || ifnull(stored_line.Discount_Amount,0) != ifnull(row.Discount_Amount,0) || ifnull(stored_line.Tax_Amount,0) != ifnull(row.Tax_Amount,0))
		{
			alert "Assign or change Sales Vouchers through Invoice Details. Invoice rows are read-only.";
			cancel submit;
		}
	}
	if(actual_count != expected_ids.size())
	{
		alert "Add or remove Draft invoice assignments through Invoice Details.";
		cancel submit;
	}
	expected_payments = Payment_Receipt_Details[Invoice == input.ID].ID.getAll();
	actual_payments = 0;
	for each  payment in input.Payment_Received_Details
	{
		actual_payments = actual_payments + 1;
		stored_payment = Payment_Receipt_Details[ID == payment.ID];
		if(!expected_payments.contains(payment.ID) || ifnull(stored_payment.Amount_Allocated,0) != ifnull(payment.Amount_Allocated,0))
		{
			alert "Record or amend payments through Payment Receipt Details.";
			cancel submit;
		}
	}
	if(actual_payments != expected_payments.size())
	{
		alert "Record or remove payments through Payment Receipt Details.";
		cancel submit;
	}
}
else
{
	for each  new_line in input.Details
	{
		alert "Create the Draft invoice first, then assign sales through Invoice Details.";
		cancel submit;
	}
	for each  new_payment in input.Payment_Received_Details
	{
		alert "Record payments through Payment Receipt Details.";
		cancel submit;
	}
}
input.Main_Customer = input.Customer.Customer;
input.Display_Name_Customer = input.Customer.Display_Name_Customer;

if(input.Cancel_Invoice == true)
{
	input.Invoice_Status = "Cancelled";
}
else if(input.Send_Invoice == true)
{
	input.Invoice_Status = "Invoiced";
	if(input.Date_Sent == null)
	{
		input.Date_Sent = zoho.currentdate;
		input.Sent_By = zoho.loginuser;
	}
}
else
{
	input.Invoice_Status = "Draft";
}
for each  d in Invoice_Details[Invoice == input.ID]
{
	if(input.Cancel_Invoice == true)
	{
		d.Invoice_Details_Status="Cancelled";
	}
	else if(d.Invoice_Details_Status != "Cancelled")
	{
		if(input.Send_Invoice == true)
		{
			d.Invoice_Details_Status="Invoiced";
		}
		else
		{
			d.Invoice_Details_Status="Draft";
			if(d.Sales_Voucher1 != null)
			{
				thisapp.sync_sales_invoice_detail(d.Sales_Voucher1);
			}
		}
	}
}
thisapp.fix_sales_vouchers_from_invoice(input.ID);

if(input.Item != null && input.Item.Booking_Mode == "Shared Session")
{
	limit = ifnull(input.Item.Session_Capacity,0);
	if(input.Number_Of_Participants == null || input.Number_Of_Participants <= 0 || input.Number_Of_Participants > limit)
	{
		alert "Enter between 1 and " + limit + " participants for this session.";
		cancel submit;
	}
}
if(input.Sales_Voucher_Date == null)
{
	input.Sales_Voucher_Date = zoho.currentdate;
}
if(input.Sales_Voucher_Number == null || input.Sales_Voucher_Number == "")
{
	doc = Document_Key[Voucher_Type == "Sales Voucher" && Document_Key_Status == "Active"];
	if(doc.ID == null)
	{
		alert "No active Document Key found for Sales Voucher.";
		cancel submit;
	}
	next_no = ifnull(doc.Next_Number,1);
	if(next_no < 10)
	{
		num_txt = "0000" + next_no;
	}
	else if(next_no < 100)
	{
		num_txt = "000" + next_no;
	}
	else if(next_no < 1000)
	{
		num_txt = "00" + next_no;
	}
	else if(next_no < 10000)
	{
		num_txt = "0" + next_no;
	}
	else
	{
		num_txt = "" + next_no;
	}
	input.Sales_Voucher_Number = doc.Prefix + "-" + num_txt;
	doc.Next_Number=next_no + 1;
}
for each  row in input.Product_Details
{
	row.Display_Name_Sales_Voucher=input.Sales_Voucher_Number;
}

