// -------------------------------
if(input.Bill == null)
{
	errors.add("• Bill is required.");
}
if(input.Expense_Type == null || input.Expense_Type == "")
{
	errors.add("• Expense Type is required.");
}
// =====================================================
// A) DOCUMENT TRANSPORT
// =====================================================
if(is_document_transport)
{
	if(input.Details_Date == null)
	{
		errors.add("• Details Date is required.");
	}
	if(input.Reference == null || input.Reference.trim() == "")
	{
		errors.add("• Reference is required.");
	}
	if(input.Details == null || input.Details.trim() == "")
	{
		errors.add("• Details is required.");
	}
	if(input.Quantity == null || input.Quantity <= 0)
	{
		errors.add("• Quantity must be greater than 0.");
	}
	if(input.Rate == null || input.Rate < 0)
	{
		errors.add("• Rate is required.");
	}
	if(input.Account == null || input.Account.trim() == "")
	{
		errors.add("• Account is required.");
	}
}
// =====================================================
// B) STORE BILL DETAILS ONLY
// =====================================================
else if(is_store_bill)
{
	if(input.Item == null)
	{
		errors.add("• Item is required.");
	}
	if(input.Unit_Of_Measure == null)
	{
		errors.add("• Unit Of Measure is required.");
	}
	if(input.Quantity == null || input.Quantity <= 0)
	{
		errors.add("• Quantity must be greater than 0.");
	}
	if(input.Rate == null || input.Rate < 0)
	{
		errors.add("• Rate is required.");
	}
	billable = ifnull(input.Quantity_Billable,0.0);
	if(input.Quantity != null && input.Quantity > billable)
	{
		errors.add("• You cannot bill more than Quantity Billable (" + billable.toString() + ").");
	}
	base_qty = ifnull(input.Quantity_In_Base_Unit,0.0);
	if(base_qty <= 0 && input.Item != null && input.Unit_Of_Measure != null && input.Quantity != null && input.Quantity > 0)
	{
		po_det = Purchase_Order_Details[ID == input.Item];
		if(po_det.ID != null && po_det.Item != null)
		{
			item_id = po_det.Item;
			check = store_management.po.check_uom_conversion_from_masaka_site_management(item_id,input.Unit_Of_Measure);
			if(check == null || check.get("ok") != true)
			{
				errors.add("• " + ifnull(check.get("message"),"UOM conversion failed."));
			}
			else
			{
				bq = store_management.po.convert_to_base_qty_from_masaka_site_management(item_id,input.Unit_Of_Measure,input.Quantity);
				if(bq != null && bq > 0)
				{
					input.Quantity_In_Base_Unit = bq;
					base_qty = bq;
				}
			}
		}
	}
	if(base_qty <= 0)
	{
		errors.add("• Quantity in Base Unit could not be calculated. Check Unit Of Measure conversion.");
	}
	line_total_val = 0.0;
	if(input.Quantity != null && input.Rate != null)
	{
		line_total_val = round(input.Quantity * input.Rate,2);
	}
	if(line_total_val > 0 && base_qty > 0)
	{
		input.Rate_In_Base_Unit = round(line_total_val / base_qty,2);
	}
	else
	{
		input.Rate_In_Base_Unit = 0.0;
	}
}
// =====================================================
// C) WORK ORDER / PARTS & CONSUMABLES BILL DETAILS
// =====================================================
else if(is_parts_bill)
{
	if(input.Details == null || input.Details.trim() == "")
	{
		errors.add("• Details is required for Parts & Consumables.");
	}
	if(input.Quantity == null || input.Quantity <= 0)
	{
		errors.add("• Quantity must be greater than 0.");
	}
	if(input.Rate == null || input.Rate < 0)
	{
		errors.add("• Rate is required.");
	}
}
// =====================================================
// D) DEFAULT / MANUAL EMPLOYEE DETAILS
// =====================================================
else
{
	if(input.Account == null || input.Account.trim() == "")
	{
		errors.add("• Account is required.");
	}
	if(input.Current_Site == null || input.Current_Site.trim() == "")
	{
		errors.add("• Current Site is required.");
	}
}
// =====================================================
// 3) Check Bill Total limit - applies to all bill types
// =====================================================
if(input.Bill != null)
{
	bill_rec = Bill[ID == input.Bill];
	if(bill_rec.ID != null)
	{
		bill_total = ifnull(bill_rec.Bill_Total,0.0);
		if(bill_total <= 0)
		{
			bill_total = ifnull(bill_rec.Amount_Due,0.0);
		}
		allowed_excess = 10.0;
		existing_total = 0.0;
		existing_lines = Bill_Details[Bill == bill_rec.ID];
		for each  row in existing_lines
		{
			if(input.ID != null && row.ID == input.ID)
			{
				continue;
			}
			existing_total = existing_total + ifnull(row.Line_Total,0.0);
		}
		current_line_total = 0.0;
		if(input.Quantity != null && input.Rate != null)
		{
			current_line_total = round(input.Quantity * input.Rate,2);
		}
		else
		{
			current_line_total = ifnull(input.Line_Total,0.0);
		}
		new_total = existing_total + current_line_total;
		excess_amount = new_total - bill_total;
		if(excess_amount > allowed_excess)
		{
			errors.add("• Details Total exceeds Bill Total by " + excess_amount.toString() + ". Maximum allowed excess is 10.");
		}
	}
}
// FINAL
if(errors.size() > 0)
{
	msg = "Please fix the following:\n\n";
	for each  err_msg in errors
	{
		msg = msg + err_msg + "\n";
	}
	alert msg;
	cancel submit;
}

// =======================================
