		cancel submit;
	}
	if(note_used > 0)
	{
		alert "Remove this note's credit allocations in Payment Receipt Details before cancelling it.";
		cancel submit;
	}
	input.Credit_Note_Status = "Cancelled";
}
else
{
	if(sv.Cancel_Voucher == true || sv.Payment_Status == "Cancelled")
	{
		alert "A cancelled Sales Voucher cannot receive credit.";
		cancel submit;
	}
	customer_record = Customer_Register[ID == input.Customer];
	if(customer_record.Credit_Allowed != true)
	{
		alert "Credit is not allowed for this customer.";
		cancel submit;
	}
	if(customer_record.Customer_Status != "Active")
	{
		alert "Select an active customer.";
		cancel submit;
	}
	paid_on_sale = 0.0;
	credited_elsewhere = 0.0;
	for each  detail in Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Sales_Voucher == sv.ID]
	{
		paid_on_sale = paid_on_sale + ifnull(detail.Amount_Allocated,0);
		if(detail.Credit_Note_Voucher != input.ID)
		{
			credited_elsewhere = credited_elsewhere + ifnull(detail.Amount_Credited,0);
		}
	}
	input.Amount_Due = round(ifnull(sv.Grand_Total,0) - paid_on_sale - credited_elsewhere,2);
	if(input.Amount_Due < 0)
	{
		input.Amount_Due = 0;
	}
	input.Credit_Limit = ifnull(customer_record.Credit_Limit,0);
	live_revenue = ifnull(Sales_Voucher[Customer == input.Customer && Payment_Status != "Cancelled" && Cancel_Voucher != true].sum(Grand_Total),0);
	live_paid = ifnull(Payment_Receipt_Voucher[Customer == input.Customer && Payment_Receipt_Voucher_Status != "Cancelled"].sum(Total_Amount_Received),0);
	input.Current_Outstanding_Balance = live_revenue - live_paid;
	if(input.Current_Outstanding_Balance < 0)
	{
		input.Current_Outstanding_Balance = 0;
	}
	input.Available_Credit = input.Credit_Limit - input.Current_Outstanding_Balance;
	if(input.Available_Credit < 0)
	{
		input.Available_Credit = 0;
	}
	if(ifnull(input.Credit_Amount,0) <= 0)
	{
		alert "Credit Amount must be greater than zero.";
		cancel submit;
	}
	if(input.Credit_Amount > input.Amount_Due)
	{
		alert "Credit Amount cannot exceed the current Amount Due.";
		cancel submit;
	}
	if(input.Credit_Amount < note_used)
	{
		alert "Credit Amount cannot be less than the credit already allocated from this note.";
		cancel submit;
	}
	// The selected sale is already part of outstanding debt.
	selected_sale_debt = ifnull(sv.Grand_Total,0) - paid_on_sale;
	if(selected_sale_debt < 0)
	{
		selected_sale_debt = 0;
	}
	other_outstanding = input.Current_Outstanding_Balance - selected_sale_debt;
	if(other_outstanding < 0)
	{
		other_outstanding = 0;
	}
	credit_capacity = input.Credit_Limit - other_outstanding;
	if(credit_capacity < 0)
	{
		credit_capacity = 0;
	}
	if(input.Credit_Amount > credit_capacity && input.Credit_Amount > note_used)
	{
		alert "Credit Amount exceeds the credit limit after allowing for this sale already included in outstanding debt.";
		cancel submit;
	}
	input.Credit_Days_Allowed = ifnull(customer_record.Credit_Days_Allowed,0);
	if(input.Credit_Days_Allowed < 0)
	{
		alert "Credit Days Allowed cannot be negative.";
		cancel submit;
	}
	if(sv.Sales_Voucher_Date == null)
	{
		alert "Sales Voucher Date is required to calculate Due Date.";
		cancel submit;
	}
	input.Due_Date = sv.Sales_Voucher_Date.addDay(input.Credit_Days_Allowed);
	input.Balance_Due = round(input.Amount_Due - input.Credit_Amount,2);
	if(note_used > 0)
	{
		input.Credit_Note_Status = "Credited";
	}
	else
	{
		input.Credit_Note_Status = "Issued";
	}
}

