			Display_Name_Voucher=input.Request_Voucher
			Line_Number=input.Line_Number
			Display_Name_Item=input.Display_Name_Item
			Quantity=input.Quantity
			Cost=input.Cost
			Item_Issuing_Detail=input.Item_Issuing_Number
			Source_Record_ID=input.ID
			Source_Form="Item Issuing Details"
			Added_User=zoho.loginuser
		]
	}
