	input.Quantity_in_Base_Unit_Of_Measure = null;
	input.Line_Total = null;
	Rate_In_Base_Unit = 0.0;
	return;
}
// Line total
input.Line_Total = (base_qty * ifnull(input.Cost,0.0)).round(2);
// Rate in base unit
if(base_qty > 0 && input.Line_Total != null && input.Line_Total > 0)
{
