	{
		total_returned = 0.0;
		total_returned_base = 0.0;
		return_rows = Stock_Receiving_Details[Receiving_Type == "Stock Return" || Receiving_Type == "Tool Return" && Item_Issuing_Details1 == input.Item_Issuing_Details1 && Stock_Receiving_Details_Status == "Received"];
		for each  ret in return_rows
		{
			total_returned = total_returned + ifnull(ret.Quantity_Received,0.0);
			total_returned_base = total_returned_base + ifnull(ret.Quantity_in_Base_Unit_Of_Measure_Received,0.0);
		}
		issue_ret.Quantity_Returned=total_returned;
		issue_ret.Quantity_Returned_in_Base_Unit_Of_Measure=total_returned_base;
		issued_base = ifnull(issue_ret.Quantity_in_Base_Unit_Of_Measure,0.0);
		if(total_returned_base >= issued_base && issued_base > 0)
		{
			issue_ret.Status="Returned";
		}
		else
		{
			if(rtype == "Tool Return")
			{
				issue_ret.Status="Borrowed";
			}
			else
			{
				issue_ret.Status="Issued";
			}
		}
	}
