if(rtype == "Purchase Order" && input.Item != null)
{
	po_det = Purchase_Order_Details[ID == input.Item];
	if(po_det.ID != null && po_det.Item != null)
	{
		bill_rows = Bill_Details[Stock_Receiving_Details == input.ID];
		for each  bd in bill_rows
		{
			delete from Bill_Details[ID == bd.ID];
		}
		total_received = 0.0;
		remaining_rows = Stock_Receiving_Details[Receiving_Type == "Purchase Order" && Item == input.Item && ID != input.ID && Stock_Receiving_Details_Status == "Received"];
		for each  rr in remaining_rows
		{
			total_received = total_received + ifnull(rr.Quantity_Received,0.0);
		}
		qty_ordered = ifnull(po_det.Quantity_Ordered,0.0);
		qty_remaining = qty_ordered - total_received;
		if(qty_remaining < 0)
		{
			qty_remaining = 0.0;
		}
		po_det.Quantity_Received=total_received;
		po_det.Quantity_Remaining=qty_remaining;
		po_det.Quantity_Billable=total_received;
		po_det.Quantity_Unbilled=total_received - ifnull(po_det.Quantity_Billed,0.0);
		if(po_det.Quantity_Unbilled < 0)
		{
			po_det.Quantity_Unbilled=0.0;
		}
		if(total_received <= 0)
		{
			po_det.Receiving_Status="Not Received";
		}
		else if(qty_remaining > 0)
		{
			po_det.Receiving_Status="Partially Received";
		}
		else
		{
			po_det.Receiving_Status="Fully Received";
		}
		if(po_det.Purchase_Order != null)
		{
			thisapp.po.update_po_receiving_status(po_det.Purchase_Order);
		}
	}
}
