			total_returned_base = total_returned_base + ifnull(ret.Quantity_in_Base_Unit_Of_Measure_Received,0.0);
		}
		issue_rec.Quantity_Returned=total_returned;
		issue_rec.Quantity_Returned_in_Base_Unit_Of_Measure=total_returned_base;
		issued_base = ifnull(issue_rec.Quantity_in_Base_Unit_Of_Measure,0.0);
		if(total_returned_base >= issued_base && issued_base > 0)
