		amount_allocated = 0.0;
		receipt_rows = Payment_Receipt_Details[Payment_Receipt_Voucher == prv.ID];
		for each  rec in receipt_rows
		{
			amount_allocated = amount_allocated + ifnull(rec.Amount_Allocated,0.0);
		}
		prv.Total_Amount_Allocated=amount_allocated;
		total_received = ifnull(prv.Total_Amount_Received,0.0);
		amount_not_allocated = total_received - total_charges - amount_allocated;
		if(amount_not_allocated < 0)
		{
			amount_not_allocated = 0.0;
		}
		prv.Total_Amount_Not_Allocated=amount_not_allocated;
		if(amount_not_allocated <= 0)
		{
			prv.Payment_Receipt_Voucher_Status="Allocated";
		}
		else if(total_charges > 0 || amount_allocated > 0)
		{
			prv.Payment_Receipt_Voucher_Status="Partially Allocated";
		}
		else
		{
			prv.Payment_Receipt_Voucher_Status="Unassigned";
