rec = Payment_Made_Voucher[ID == input.ID];
if(rec.ID != null)
{
	if(rec.Payment_Made_Date == null)
	{
		rec.Payment_Made_Date=zoho.currenttime;
	}
	total_charges = 0.0;
	for each  ch in rec.Charge_Details
	{
		total_charges = total_charges + ifnull(ch.Amount,0.0);
	}
	total_allocated = 0.0;
	for each  det in rec.Made_Details
	{
		paid_amt = ifnull(det.Amount_Paid,0.0);
		det.Amount_Allocated=paid_amt;
		total_allocated = total_allocated + paid_amt;
		if(det.Bill != null)
		{
			bill_rec = Bill[ID == det.Bill];
			if(bill_rec.ID != null)
			{
				total_paid_for_bill = 0.0;
				for each  pmv in Payment_Made_Voucher[ID != null]
				{
					for each  row2 in pmv.Made_Details
					{
						if(row2.Bill == bill_rec.ID)
						{
							total_paid_for_bill = total_paid_for_bill + ifnull(row2.Amount_Paid,0.0);
						}
					}
				}
				original_bill_amount = ifnull(bill_rec.Total_Amount,0.0);
				bill_rec.Amount_Paid=total_paid_for_bill;
				new_due = original_bill_amount - total_paid_for_bill;
				if(new_due < 0)
				{
					new_due = 0.0;
				}
				bill_rec.Amount_Due=new_due;
				bill_rec.Balance_Due=new_due;
				if(new_due <= 0)
				{
					bill_rec.Payment_Status="Paid";
				}
				else if(total_paid_for_bill > 0)
				{
					bill_rec.Payment_Status="Partially Paid";
				}
				else
				{
					bill_rec.Payment_Status="Unpaid";
				}
				if(paid_amt > 0)
				{
					post = Map();
					post.put("Display_Name_Application","Freedom City Arena Management");
					post.put("Source_Form","Payment Made Details");
					post.put("Source_Record_ID",det.ID.toString());
					post.put("Voucher_Number",ifnull(rec.Payment_Made_Number,""));
					post.put("Transaction_Date",rec.Payment_Made_Date);
					post.put("Business_Division",null);
					post.put("Display_Name_Business_Division","");
					post.put("Amount_To_Receive",0.0);
					post.put("Amount_Received",0.0);
					post.put("Amount_Not_Received",0.0);
					post.put("Amount_To_Pay",0.0);
					post.put("Amount_Paid",paid_amt);
					post.put("Amount_Not_Paid",0.0);
					grapes_group.concreteproducts.postBusinessDivisionDetail(post);
				}
			}
		}
	}
	rec.Total_Charges=total_charges;
	rec.Total_Amount_Allocated=total_allocated;
	rec.Total_Amount_Not_Allocated=ifnull(rec.Total_Amount_Paid,0.0) - total_charges - total_allocated;
	if(rec.Total_Amount_Not_Allocated < 0)
	{
		rec.Total_Amount_Not_Allocated=0.0;
	}
	if(total_allocated == 0)
	{
		rec.Payment_Made_Voucher_Status="Unassigned";
	}
	else if(rec.Total_Amount_Not_Allocated > 0)
	{
		rec.Payment_Made_Voucher_Status="Partially Assigned";
	}
	else
	{
		rec.Payment_Made_Voucher_Status="Fully Assigned";
	}
}
