	{
		alert "Amount Allocated is required and must be greater than zero.";
		cancel submit;
	}
}
// =====================================
// PAYMENT DOCUMENT VALIDATION
// =====================================
if(input.Payment_Document == "Sales Voucher")
{
	if(input.Sales_Voucher == null)
	{
		alert "Please select Sales Voucher.";
		cancel submit;
	}
}
else if(input.Payment_Document == "Invoice")
{
	if(input.Invoice == null)
	{
		alert "Please select Invoice.";
		cancel submit;
	}
}
// Customer comes from the selected receipt, and must match the sales voucher.
if(input.Payment_Type == "Cash" && input.Payment_Receipt_Voucher != null)
{
	input.Customer = ifnull(input.Payment_Receipt_Voucher.Customer.Display_Name_Customer,"");
	if(input.Payment_Document == "Sales Voucher" && input.Sales_Voucher != null)
	{
		if(input.Sales_Voucher.Customer != input.Payment_Receipt_Voucher.Customer)
		{
			alert "The Sales Voucher customer must match the Payment Receipt customer.";
			cancel submit;
		}
	}
}
// Check deposit availability from stored receipt and usage records.
if(input.Payment_Type == "Cash Deposit" && input.Customer_Deposit_Voucher != null)
{
	deposit_source = Customer_Deposit_Details[ID == input.Customer_Deposit_Voucher];
	deposit_incoming = ifnull(Payment_Receipt_Details[Payment_Type == "Cash" && Payment_Document == "Cash Deposit" && Customer_Deposit_Number == deposit_source.ID].sum(Amount_Allocated),0);
	deposit_used_elsewhere = ifnull(Payment_Receipt_Details[Payment_Type == "Cash Deposit" && Customer_Deposit_Voucher == deposit_source.ID && ID != input.ID].sum(Amount_Allocated),0);
	live_deposit_available = round(deposit_incoming - ifnull(deposit_source.Total_Charges,0) - deposit_used_elsewhere,2);
	if(input.Amount_Allocated > live_deposit_available)
	{
		alert "Amount Allocated exceeds the current available customer deposit balance.";
		cancel submit;
	}
	input.Amount_Not_Allocated = live_deposit_available;
	input.Customer = ifnull(deposit_source.Display_Name_Customer,"");
	if(input.Payment_Document == "Sales Voucher" && input.Sales_Voucher != null && input.Sales_Voucher.Customer != deposit_source.Customer)
	{
		alert "The Sales Voucher customer must match the customer deposit.";
		cancel submit;
	}
}
if(input.Payment_Type == "Cash" && input.Payment_Document == "Cash Deposit")
{
	if(input.Customer_Deposit_Number == null)
	{
		alert "Please select Customer Deposit Number.";
		cancel submit;
	}
	if(input.Amount_Allocated == null || input.Amount_Allocated <= 0)
	{
		alert "Amount Allocated is required and must be greater than zero.";
		cancel submit;
	}
	deposit_target = Customer_Deposit_Details[ID == input.Customer_Deposit_Number];
	if(input.Payment_Receipt_Voucher.Customer != deposit_target.Customer)
	{
		alert "The receipt customer must match the customer deposit.";
		cancel submit;
	}
	receipt_used_elsewhere = ifnull(Payment_Receipt_Details[Payment_Receipt_Voucher == input.Payment_Receipt_Voucher && ID != input.ID].sum(Amount_Allocated),0);
	receipt_available = round(ifnull(input.Payment_Receipt_Voucher.Total_Amount_Received,0) - ifnull(input.Payment_Receipt_Voucher.Total_Charges,0) - receipt_used_elsewhere,2);
	if(input.Amount_Allocated > receipt_available)
	{
		alert "Amount Allocated exceeds the current available receipt balance.";
		cancel submit;
	}
	deposit_other_receipts = ifnull(Payment_Receipt_Details[Payment_Type == "Cash" && Payment_Document == "Cash Deposit" && Customer_Deposit_Number == deposit_target.ID && ID != input.ID].sum(Amount_Allocated),0);
	deposit_existing_usage = ifnull(Payment_Receipt_Details[Payment_Type == "Cash Deposit" && Customer_Deposit_Voucher == deposit_target.ID].sum(Amount_Allocated),0);
	if(deposit_other_receipts + input.Amount_Allocated < deposit_existing_usage + ifnull(deposit_target.Total_Charges,0))
	{
		alert "This change would reduce the deposit below the amount already used. Reduce the deposit allocations first.";
		cancel submit;
	}
}
// A credit allocation must use an active note for its linked sale.
if(input.Payment_Type == "Credit" && input.Credit_Note_Voucher != null)
{
	selected_note = Credit_Note[ID == input.Credit_Note_Voucher];
	if(selected_note.Cancel_Credit_Note_Voucher == true || selected_note.Credit_Note_Status == "Cancelled")
	{
		alert "A cancelled Credit Note cannot be allocated.";
		cancel submit;
	}
	if(input.Payment_Document != "Sales Voucher" || input.Sales_Voucher != selected_note.Sales_Voucher)
	{
		alert "Credit must be allocated to the Sales Voucher recorded on the Credit Note.";
		cancel submit;
	}
	other_note_credit = ifnull(Payment_Receipt_Details[Credit_Note_Voucher == selected_note.ID && ID != input.ID].sum(Amount_Credited),0);
	remaining_note_credit = round(ifnull(selected_note.Credit_Amount,0) - other_note_credit,2);
	input.Amount_Allocated = 0;
	input.Amount_Not_Allocated = 0;
	input.Payment_Receipt_Voucher = null;
	input.Customer_Deposit_Voucher = null;
	input.Customer_Deposit_Number = null;
	input.Invoice = null;
	input.Display_Name_Voucher = selected_note.Credit_Note_Number;
	input.Display_Name_Invoice_Voucher = selected_note.Sales_Voucher.Sales_Voucher_Number;
	paid_elsewhere = ifnull(Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Sales_Voucher == input.Sales_Voucher && ID != input.ID].sum(Amount_Allocated),0);
	credited_elsewhere = ifnull(Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Sales_Voucher == input.Sales_Voucher && ID != input.ID].sum(Amount_Credited),0);
	input.Amount_Due = round(ifnull(input.Sales_Voucher.Grand_Total,0) - paid_elsewhere - credited_elsewhere,2);
	if(input.Amount_Due < 0)
	{
		input.Amount_Due = 0;
	}
	if(input.Amount_Credited > input.Amount_Due)
	{
		alert "Amount Credited exceeds the current unpaid balance of this Sales Voucher.";
		cancel submit;
	}
	input.Balance_Due = round(input.Amount_Due - input.Amount_Credited,2);
	if(input.Amount_Credited > remaining_note_credit)
	{
		alert "Amount Credited exceeds the remaining credit on this note.";
		cancel submit;
	}
	input.Customer = ifnull(selected_note.Display_Name_Customer,"");
}
if(input.Payment_Type != "Credit")
{
	input.Amount_Credited = 0;
	input.Credit_Note_Voucher = null;
}
// Preserve allocation ownership on edit so both ledgers remain reconciled.
previous_detail = Payment_Receipt_Details[ID == input.ID];
if(previous_detail.ID != null)
{
	if(previous_detail.Payment_Document != input.Payment_Document || previous_detail.Sales_Voucher != input.Sales_Voucher || previous_detail.Invoice != input.Invoice || previous_detail.Payment_Type != input.Payment_Type || previous_detail.Payment_Receipt_Voucher != input.Payment_Receipt_Voucher || previous_detail.Customer_Deposit_Voucher != input.Customer_Deposit_Voucher || previous_detail.Customer_Deposit_Number != input.Customer_Deposit_Number || previous_detail.Credit_Note_Voucher != input.Credit_Note_Voucher)
	{
		alert "Edit the amount on the existing allocation. Use a separate record for a different source or document.";
		cancel submit;
	}
}
if(input.Payment_Type == "Cash")
{
	receipt = Payment_Receipt_Voucher[ID == input.Payment_Receipt_Voucher];
	if(receipt.Payment_Receipt_Voucher_Status == "Cancelled")
	{
		alert "A cancelled receipt cannot be allocated.";
		cancel submit;
	}
	receipt_used = ifnull(Payment_Receipt_Details[Payment_Receipt_Voucher == receipt.ID && ID != input.ID].sum(Amount_Allocated),0);
	available = round(ifnull(receipt.Total_Amount_Received,0) - ifnull(receipt.Total_Charges,0) - receipt_used,2);
	if(ifnull(input.Amount_Allocated,0) > available)
	{
		alert "Amount Allocated exceeds the unused money on this receipt.";
		cancel submit;
	}
}
if(input.Payment_Document == "Invoice")
{
	inv = Invoice[ID == input.Invoice];
	if(input.Payment_Type == "Credit" || inv.Cancel_Invoice == true || inv.Invoice_Status != "Invoiced" || inv.Send_Invoice != true)
	{
		alert "Payment cannot be recorded while the Invoice is Draft or cancelled. Send an active Invoice first, then pay using a receipt or customer deposit.";
		cancel submit;
	}
	if(input.Payment_Type == "Cash" && inv.Customer != input.Payment_Receipt_Voucher.Customer)
	{
		alert "Invoice and receipt customers must match.";
		cancel submit;
	}
	if(input.Payment_Type == "Cash Deposit" && inv.Customer != input.Customer_Deposit_Voucher.Customer)
	{
		alert "Invoice and deposit customers must match.";
		cancel submit;
	}
	other_paid = 0.0;
	for each  allocation in Payment_Receipt_Details[Payment_Document == "Invoice" && Invoice == inv.ID && ID != input.ID]
	{
		if(allocation.Payment_Receipt_Voucher == null || allocation.Payment_Receipt_Voucher.Payment_Receipt_Voucher_Status != "Cancelled")
		{
			other_paid = other_paid + ifnull(allocation.Amount_Allocated,0);
		}
	}
	original_paid = 0.0;
	seen = List();
	for each  line in Invoice_Details[Invoice == inv.ID && Invoice_Details_Status != "Cancelled"]
	{
		if(line.Sales_Voucher1 != null && !seen.contains(line.Sales_Voucher1))
		{
			seen.add(line.Sales_Voucher1);
			original_paid = original_paid + ifnull(line.Sales_Voucher1.Amount_Paid,0);
		}
	}
	debt = round(ifnull(inv.Grand_Total,0) - original_paid - other_paid,2);
	if(ifnull(input.Amount_Allocated,0) > debt)
	{
		alert "Amount Allocated exceeds the invoice's actual outstanding balance.";
		cancel submit;
	}
	input.Amount_Due = debt;
	input.Balance_Due = round(debt - ifnull(input.Amount_Allocated,0),2);
}
if(input.Payment_Document == "Sales Voucher" && input.Payment_Type != "Credit")
{
	sv = Sales_Voucher[ID == input.Sales_Voucher];
	if(sv.Cancel_Voucher == true)
	{
		alert "A cancelled Sales Voucher cannot receive payments.";
		cancel submit;
	}
	other_cash = ifnull(Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Sales_Voucher == sv.ID && ID != input.ID].sum(Amount_Allocated),0);
	other_credit = ifnull(Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Sales_Voucher == sv.ID && ID != input.ID].sum(Amount_Credited),0);
	available_sale = round(ifnull(sv.Grand_Total,0) - other_cash - other_credit - ifnull(sv.Paid_Through_Invoice,0),2);
	if(ifnull(input.Amount_Allocated,0) > available_sale)
	{
		alert "Amount Allocated exceeds the unallocated Sales Voucher balance. Clear credited debt against its invoice.";
		cancel submit;
	}
}

// ======================================================
// PAYMENT RECEIPT DETAILS — FINALIZE
// ======================================================
// 1. UPDATE PAYMENT RECEIPT VOUCHER
if(input.Payment_Receipt_Voucher != null)
{
	prv = Payment_Receipt_Voucher[ID == input.Payment_Receipt_Voucher];
	if(prv.ID != null)
	{
		total_charges = 0.0;
		for each  ch in Payment_Charges[Payment_Receipt_Voucher == prv.ID]
		{
			total_charges = total_charges + ifnull(ch.Amount,0.0);
		}
		detail_allocated = 0.0;
		for each  det in Payment_Receipt_Details[Payment_Receipt_Voucher == prv.ID]
		{
			detail_allocated = detail_allocated + ifnull(det.Amount_Allocated,0.0);
		}
		amount_allocated = total_charges + detail_allocated;
		balance = ifnull(prv.Total_Amount_Received,0.0) - amount_allocated;
		if(balance < 0)
		{
			balance = 0.0;
		}
		prv.Total_Charges=total_charges;
		prv.Total_Amount_Allocated=amount_allocated;
		prv.Total_Amount_Not_Allocated=balance;
		if(balance <= 0)
		{
			prv.Payment_Receipt_Voucher_Status="Fully Assigned";
		}
		else if(amount_allocated > 0)
		{
			prv.Payment_Receipt_Voucher_Status="Partially Assigned";
		}
		else
		{
			prv.Payment_Receipt_Voucher_Status="Unassigned";
		}
	}
}
// =====================================================
// IF PAYMENT IS FOR SALES VOUCHER
// =====================================================
if(input.Payment_Document == "Sales Voucher" && input.Sales_Voucher != null)
{
	sv = Sales_Voucher[ID == input.Sales_Voucher.ID];
	if(sv.ID != null)
	{
		total_paid = 0.0;
		total_credited = 0.0;
		for each  det2 in Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Sales_Voucher == sv.ID]
		{
			total_paid = total_paid + ifnull(det2.Amount_Allocated,0.0);
			total_credited = total_credited + ifnull(det2.Amount_Credited,0.0);
		}
		sv_total = ifnull(sv.Grand_Total,0.0);
		if(total_paid > sv_total)
		{
			total_paid = sv_total;
		}
		sv.Amount_Paid=total_paid;
		sv.Amount_Credited=total_credited;
		sv.Balance_Due=sv_total - total_paid - total_credited;
		if(sv.Balance_Due < 0)
		{
			sv.Balance_Due=0.0;
		}
		if(sv.Balance_Due <= 0)
		{
			if(total_credited > 0)
			{
				sv.Payment_Status="Credit";
			}
			else
			{
				sv.Payment_Status="Paid";
			}
		}
		else if(total_credited > 0)
		{
			sv.Payment_Status="Partially Credited";
		}
		else if(total_paid > 0)
		{
			sv.Payment_Status="Partially Paid";
		}
		else
		{
			sv.Payment_Status="Unpaid";
		}
	}
}
// =====================================================
// IF PAYMENT IS FOR INVOICE
// =====================================================
if(input.Payment_Document == "Invoice" && input.Invoice != null)
{
	thisapp.fix_sales_vouchers_from_invoice(input.Invoice.ID);
}
// 2B. POST PAYMENT RECEIPT DETAILS TO GRAPES GROUP
if(input.Payment_Document == "Sales Voucher" && input.Sales_Voucher != null)
{
	amount_to_post = ifnull(input.Amount_Allocated,0.0);
	if(amount_to_post > 0)
	{
		post = Map();
		post.put("Display_Name_Application","Freedom City Arena Management");
		post.put("Source_Form","Payment Receipt Details");
		post.put("Source_Record_ID",input.ID.toString());
		post.put("Voucher_Number",input.Display_Name_Voucher);
		post.put("Transaction_Date",input.Payment_Receipt_Voucher.Payment_Receipt_Date);
		post.put("Business_Division",null);
		post.put("Display_Name_Business_Division","");
		post.put("Amount_To_Receive",0);
		post.put("Amount_Received",amount_to_post);
		post.put("Amount_Not_Received",0);
		post.put("Amount_To_Pay",0);
		post.put("Amount_Paid",0);
		post.put("Amount_Not_Paid",0);
		grapes_group.concreteproducts.postBusinessDivisionDetail(post);
	}
}
// Invoice Details are created and updated by the physical Credit Note workflow.
// =====================================================
// SECTION: SYNC PAYMENT RECEIPT DETAILS TO PAYMENT MANAGEMENT
// =====================================================
if(input.ID != null && input.Payment_Type == "Cash")
{
	// ---------------------------------
	// Build Description
	// ---------------------------------
	description = "";
	doc_name = "";
	if(ifnull(input.Display_Name_Invoice_Voucher,"") != "")
	{
		doc_name = input.Display_Name_Invoice_Voucher;
		if(doc_name.contains(" - "))
		{
			doc_name = doc_name.getPrefix(" - ");
		}
	}
	if(ifnull(input.Payment_Document,"") != "")
	{
		description = input.Payment_Document;
	}
	if(doc_name != "")
	{
		if(description != "")
		{
			description = description + " - ";
		}
		description = description + doc_name;
	}
	// ---------------------------------
	// Amount To Sync
	// ---------------------------------
	sync_amount = ifnull(input.Amount_Allocated,0.0);
	if(input.Payment_Document == "Cash Deposit" && sync_amount <= 0)
	{
		sync_amount = ifnull(input.Amount_Not_Allocated,0.0);
	}
	// ---------------------------------
	// Transaction Date
	// ---------------------------------
	transaction_date_txt = "";
	if(input.Payment_Receipt_Voucher.Payment_Receipt_Date != null)
	{
		transaction_date_txt = input.Payment_Receipt_Voucher.Payment_Receipt_Date.toString("dd-MMM-yyyy");
	}
	// ---------------------------------
	// Created / Updated Time
	// ---------------------------------
	created_time_txt = "";
	if(input.Created_By_Time != null)
	{
		created_time_txt = input.Created_By_Time.toString("dd-MMM-yyyy HH:mm:ss");
	}
	updated_time_txt = "";
	if(input.Updated_By_Time != null)
	{
		updated_time_txt = input.Updated_By_Time.toString("dd-MMM-yyyy HH:mm:ss");
	}
	// ---------------------------------
	// Build Payload
	// ---------------------------------
	payload = Map();
	payload.put("Payment_Voucher_Source_ID",input.Payment_Receipt_Voucher.ID.toLong());
	payload.put("Display_Name_Payment_Voucher",ifnull(input.Display_Name_Voucher,""));
	payload.put("Line_Number",input.Line_Number);
	payload.put("Description",description);
	payload.put("Amount_Allocated",sync_amount);
	payload.put("Application","Freedom City Arena Management");
	payload.put("Transaction_Date",transaction_date_txt);
	payload.put("Source_Form","Payment Receipt Details");
	payload.put("Source_Record_ID",input.ID.toLong());
	payload.put("Voucher_Number",ifnull(input.Payment_Receipt_Voucher.Payment_Receipt_Number,""));
	payload.put("User_Name",ifnull(input.User_Name,""));
	payload.put("User_Email",ifnull(input.User_Email,""));
	payload.put("User_Role",ifnull(input.User_Role,""));
	payload.put("Created_By_Name",ifnull(input.Created_By_Name,""));
	payload.put("Created_By_Email",ifnull(input.Created_By_Email,""));
	payload.put("Created_By_Time",created_time_txt);
	payload.put("Updated_By_Name",ifnull(input.Updated_By_Name,""));
	payload.put("Updated_By_Email",ifnull(input.Updated_By_Email,""));
	payload.put("Updated_By_Time",updated_time_txt);
	sync_resp = payment_management.syncPaymentDetailsFromFreedomArena(payload);
	info sync_resp;
	if(sync_resp != null && sync_resp.get("ok") == true && sync_resp.get("account_id") != null)
	{
		payment_management.refreshAccountTransactionLog(sync_resp.get("account_id").toLong());
	}
}
// Recalculate each affected deposit from receipt and usage records.
affected_deposits = List();
if(input.Customer_Deposit_Number != null)
{
	affected_deposits.add(input.Customer_Deposit_Number);
}
if(input.Customer_Deposit_Voucher != null && !affected_deposits.contains(input.Customer_Deposit_Voucher))
{
	affected_deposits.add(input.Customer_Deposit_Voucher);
}
for each  deposit_id in affected_deposits
{
	cd = Customer_Deposit_Details[ID == deposit_id];
	if(cd.ID != null)
	{
		deposit_received = 0.0;
		for each  incoming_detail in Payment_Receipt_Details[Payment_Type == "Cash" && Payment_Document == "Cash Deposit" && Customer_Deposit_Number == cd.ID]
		{
			deposit_received = deposit_received + ifnull(incoming_detail.Amount_Allocated,0.0);
		}
		deposit_allocated = 0.0;
		for each  usage_detail in Payment_Receipt_Details[Payment_Type == "Cash Deposit" && Customer_Deposit_Voucher == cd.ID]
		{
			deposit_allocated = deposit_allocated + ifnull(usage_detail.Amount_Allocated,0.0);
		}
		cd.Total_Amount_Received=round(deposit_received,2);
		cd.Total_Amount_Allocated=round(deposit_allocated,2);
		deposit_available = round(deposit_received - ifnull(cd.Total_Charges,0.0) - deposit_allocated,2);
		if(deposit_available < 0)
		{
			deposit_available = 0.0;
		}
		cd.Total_Amount_Not_Allocated=deposit_available;
		if(deposit_allocated <= 0)
		{
			cd.Customer_Deposit_Status="Unassigned";
		}
		else if(deposit_available > 0)
		{
			cd.Customer_Deposit_Status="Partially Assigned";
		}
		else
		{
			cd.Customer_Deposit_Status="Fully Assigned";
		}
	}
}
// Refresh the physical Credit Note's allocation status.
if(input.Credit_Note_Voucher != null)
{
	cn = Credit_Note[ID == input.Credit_Note_Voucher];
	if(cn.ID != null && cn.Cancel_Credit_Note_Voucher != true && cn.Credit_Note_Status != "Cancelled")
	{
		note_credit_used = ifnull(Payment_Receipt_Details[Payment_Type == "Credit" && Credit_Note_Voucher == cn.ID].sum(Amount_Credited),0);
		if(note_credit_used > 0)
		{
			cn.Credit_Note_Status="Credited";
		}
		else
		{
			cn.Credit_Note_Status="Issued";
		}
	}
}
if(input.Payment_Document == "Sales Voucher" && input.Sales_Voucher != null)
{
	thisapp.sync_sales_invoice_detail(input.Sales_Voucher);
}

// ======================================================
// PAYMENT RECEIPT DETAILS — ON DELETE
// ======================================================
if(input.Payment_Receipt_Voucher != null)
{
	prv = Payment_Receipt_Voucher[ID == input.Payment_Receipt_Voucher];
	if(prv.ID != null)
	{
		total_charges = 0.0;
		for each  ch in Payment_Charges[Payment_Receipt_Voucher == prv.ID]
		{
			total_charges = total_charges + ifnull(ch.Amount,0.0);
		}
		detail_allocated = 0.0;
		for each  det in Payment_Receipt_Details[Payment_Receipt_Voucher == prv.ID && ID != input.ID]
		{
			detail_allocated = detail_allocated + ifnull(det.Amount_Allocated,0.0);
		}
		amount_allocated = total_charges + detail_allocated;
		total_received = ifnull(prv.Total_Amount_Received,0.0);
		balance = total_received - amount_allocated;
		if(balance < 0)
		{
			balance = 0.0;
		}
		prv.Total_Charges=total_charges;
		prv.Total_Amount_Allocated=amount_allocated;
		prv.Total_Amount_Not_Allocated=balance;
		if(balance <= 0)
		{
			prv.Payment_Receipt_Voucher_Status="Fully Assigned";
		}
		else if(amount_allocated > 0)
		{
			prv.Payment_Receipt_Voucher_Status="Partially Assigned";
		}
		else
		{
			prv.Payment_Receipt_Voucher_Status="Unassigned";
		}
	}
}
// Recalculate the affected Sales Voucher from remaining allocation records.
if(input.Payment_Document == "Sales Voucher" && input.Sales_Voucher != null)
{
	sv = Sales_Voucher[ID == input.Sales_Voucher];
	if(sv.ID != null)
	{
		total_paid = 0.0;
		total_credited = 0.0;
		for each  remaining_detail in Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Sales_Voucher == sv.ID && ID != input.ID]
		{
			total_paid = total_paid + ifnull(remaining_detail.Amount_Allocated,0.0);
			total_credited = total_credited + ifnull(remaining_detail.Amount_Credited,0.0);
		}
		sv_total = ifnull(sv.Grand_Total,0.0);
		if(total_paid > sv_total)
		{
			total_paid = sv_total;
		}
		sv.Amount_Paid=round(total_paid,2);
		sv.Amount_Credited=round(total_credited,2);
		remaining_balance = round(sv_total - total_paid - total_credited,2);
		if(remaining_balance < 0)
		{
			remaining_balance = 0.0;
		}
		sv.Balance_Due=remaining_balance;
		if(sv.Payment_Status != "Cancelled" && sv.Cancel_Voucher != true)
		{
			if(remaining_balance <= 0)
			{
				if(total_credited > 0)
				{
					sv.Payment_Status="Credit";
				}
				else
				{
					sv.Payment_Status="Paid";
				}
			}
			else if(total_credited > 0)
			{
				sv.Payment_Status="Partially Credited";
			}
			else if(total_paid > 0)
			{
				sv.Payment_Status="Partially Paid";
			}
			else
			{
				sv.Payment_Status="Unpaid";
			}
		}
	}
