if(input.Item == null || input.Unit_Of_Measure == null)
{
	input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = null;
	input.Quantity_Remaining = null;
	input.Quantity_Remaining_in_Base_Unit_Of_Measure = null;
	input.Line_Total = null;
}
else
{
	check = store_management.po.check_uom_conversion_from_concrete(input.Item,input.Unit_Of_Measure);
	if(check.get("ok") != true)
	{
		alert check.get("message");
		input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = null;
		input.Quantity_Remaining = null;
		input.Quantity_Remaining_in_Base_Unit_Of_Measure = null;
		input.Line_Total = null;
	}
	else
	{
		resp = store_management.po.recalculate_po_detail_line_from_concrete(input.Item,input.Unit_Of_Measure,input.Quantity_To_Be_Returned,input.Unit_Price);
		input.Display_Name_Unit_Of_Measure = resp.get("display_uom_name");
		input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = ifnull(resp.get("qty_in_base"),0.0);
		input.Line_Total = ifnull(resp.get("line_total"),0.0);
		if(ifnull(input.Quantity_To_Be_Returned,0.0) > ifnull(input.Quantity_Sold,0.0))
		{
			alert "Quantity to be returned cannot exceed quantity sold.";
			input.Quantity_To_Be_Returned = ifnull(input.Quantity_Sold,0.0);
		}
		input.Quantity_Remaining = ifnull(input.Quantity_Sold,0.0) - ifnull(input.Quantity_To_Be_Returned,0.0);
		input.Quantity_Remaining_in_Base_Unit_Of_Measure = ifnull(input.Quantity_Sold_in_Base_Unit_Of_Measure,0.0) - ifnull(input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure,0.0);
	}
}

if(input.Sales_Return_Number != null)
{
	sr = Sales_Return[ID == input.Sales_Return_Number];
	if(sr.ID != null)
	{
		input.Display_Name_Sales_Return_Number = sr.Sales_Return_Number;
		input.Customer = sr.Customer;
		last_line = 0;
		for each  d in Sales_Return_Details[Sales_Return_Number == sr.ID]
		{
			if(ifnull(d.Line_Number,0) > last_line)
			{
				last_line = d.Line_Number;
			}
		}
		input.Line_Number = last_line + 1;
		input.Sales_Return_Detail_Number = sr.Sales_Return_Number + " - " + input.Line_Number.toString();
	}
}
else
{
	input.Display_Name_Sales_Return_Number = "";
	input.Customer = null;
	input.Line_Number = null;
	input.Sales_Return_Detail_Number = "";
}

if(input.Sales_Voucher_Detail != null)
{
	svd = Sales_Voucher_Details[ID == input.Sales_Voucher_Detail];
	if(svd.ID != null)
	{
		input.Display_Name_Sales_Voucher_Detail = ifnull(svd.Display_Name_Sales_Voucher,"") + " - " + ifnull(svd.Line_Number,0).toString();
		input.Item = svd.Item;
		input.Display_Name_Item = svd.Display_Name_Item;
		input.Quantity_Sold = ifnull(svd.Quantity,0.0);
		input.Unit_Of_Measure = svd.Base_Unit_Of_Measure;
		input.Display_Name_Unit_Of_Measure = svd.Display_Name_Unit_Of_Measure;
		input.Quantity_Sold_in_Base_Unit_Of_Measure = ifnull(svd.Quantity_in_Base_Unit_Of_Measure,0.0);
		input.Unit_Price = ifnull(svd.Unit_Price,0.0);
	}
}
else
{
	input.Display_Name_Sales_Voucher_Detail = "";
	input.Item = null;
	input.Display_Name_Item = "";
	input.Quantity_Sold = 0.0;
	input.Unit_Of_Measure = null;
	input.Display_Name_Unit_Of_Measure = "";
	input.Quantity_Sold_in_Base_Unit_Of_Measure = 0.0;
	input.Unit_Price = 0.0;
}

if(input.Item == null || input.Unit_Of_Measure == null)
{
	input.Display_Name_Unit_Of_Measure = input.Unit_Of_Measure.Unit_Of_Measure_Name;
	input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = null;
	input.Line_Total = null;
	return;
}
if(input.Quantity_To_Be_Returned == null || input.Quantity_To_Be_Returned <= 0)
{
	input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = null;
	input.Line_Total = null;
	return;
}
if(input.Quantity_To_Be_Returned > ifnull(input.Quantity_Sold,0.0))
{
	alert "Quantity to be returned cannot be greater than quantity sold.";
	input.Quantity_To_Be_Returned = ifnull(input.Quantity_Sold,0.0);
}
check = store_management.po.check_uom_conversion_from_concrete(input.Item.ID,input.Unit_Of_Measure.ID);
if(check == null || check.get("ok") != true)
{
	msg = "Unit of Measure conversion is missing.";
	if(check != null)
	{
		msg = ifnull(check.get("message"),msg);
	}
	alert msg;
	input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = null;
	input.Line_Total = null;
	return;
}
base_qty = store_management.po.convert_to_base_qty_from_concrete(input.Item.ID,input.Unit_Of_Measure.ID,input.Quantity_To_Be_Returned);
if(base_qty == null || base_qty <= 0)
{
	alert "Calculated base quantity is invalid.";
	input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = null;
	input.Line_Total = null;
	return;
}
if(base_qty > ifnull(input.Quantity_Sold_in_Base_Unit_Of_Measure,0.0))
{
	alert "Quantity to be returned cannot be greater than quantity sold in base unit.";
	input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = null;
	input.Line_Total = null;
	return;
}
input.Quantity_To_Be_Returned_in_Base_Unit_Of_Measure = base_qty;
input.Line_Total = (base_qty * ifnull(input.Unit_Price,0.0)).round(2);

if(input.Sales_Return_Number == null)
{
	alert "Sales Return Number is required.";
	cancel submit;
}
if(input.Sales_Voucher_Detail == null)
{
	alert "Sales Voucher Detail is required.";
	cancel submit;
}
if(input.Item == null)
{
	alert "Item is required.";
	cancel submit;
}
if(input.Quantity_Sold == null)
{
