if(input.Vendor_Code == null || input.Vendor_Code.trim() == "")
{
	if(input.Vendor_Type == "Cash")
	{
		seq = Sequences[Sequence_Key == "VENDOR" && Is_Active == true];
		if(seq.ID == null)
		{
			alert "Vendor sequence is not configured.";
			cancel submit;
		}
		prefix_value = "VND";
		next_no = ifnull(seq.Next_Number,1);
		max_no = ifnull(seq.Max_Number,999999);
		if(next_no > max_no)
		{
			alert "Vendor sequence has reached the maximum number.";
			cancel submit;
		}
		if(next_no < 10)
		{
			num_text = "00" + next_no;
		}
		else if(next_no < 100)
		{
			num_text = "0" + next_no;
		}
		else if(next_no < 1000)
		{
			num_text = "0" + next_no;
		}
		else
		{
			num_text = next_no.toString();
		}
		input.Vendor_Code = prefix_value + num_text;
		seq.Next_Number=next_no + 1;
	}
	else
	{
		input.Vendor_Code = "";
	}
}

