{
	line_text = "0" + line_no;
}
else
{
	line_text = line_no.toString();
}
row.Display_Name_Material_Request_Voucher=input.Material_Request_Number + "-" + line_text;
row.Work_Order_Task_Number=input.Work_Order_Task;

for each  req_det in input.Material_Request_Details
{
	if(req_det.Item != null)
	{
		item_name = ifnull(req_det.Item.Item_Name,"").trim();
		item_sku = ifnull(req_det.Item.SKU,"").trim();
		req_det.Display_Name_Item=if(item_sku != "",item_name + " - " + item_sku,item_name);
		req_det.SKU=item_sku;
		if(req_det.Unit_Of_Measure == null)
		{
			req_det.Unit_Of_Measure=req_det.Item.Base_Unit_Of_Measure;
		}
		if(req_det.Unit_Of_Measure != null)
		{
			req_det.Display_Name_Unit_Of_Measure=req_det.Unit_Of_Measure.Unit_Of_Measure_Name;
		}
		else
		{
			req_det.Display_Name_Unit_Of_Measure=null;
		}
	}
	else
	{
		req_det.Display_Name_Item=null;
		req_det.SKU=null;
		req_det.Unit_Of_Measure=null;
		req_det.Display_Name_Unit_Of_Measure=null;
		req_det.Quantity_in_Base_Unit_Of_Measure=null;
		continue;
	}
	if(req_det.Item != null && req_det.Unit_Of_Measure != null)
	{
		check = store_management.po.check_uom_conversion_from_masaka_site_management(req_det.Item,req_det.Unit_Of_Measure);
		if(check == null || check.get("ok") != true)
		{
			alert ifnull(check.get("message"),"UOM conversion failed.");
			req_det.Unit_Of_Measure=null;
			req_det.Display_Name_Unit_Of_Measure=null;
			req_det.Quantity_in_Base_Unit_Of_Measure=null;
		}
		else
		{
			base_qty = store_management.po.convert_to_base_qty_from_masaka_site_management(req_det.Item,req_det.Unit_Of_Measure,ifnull(req_det.Quantity,0.0));
			if(base_qty != null && base_qty > 0)
			{
				req_det.Quantity_in_Base_Unit_Of_Measure=base_qty;
			}
			else
			{
				req_det.Quantity_in_Base_Unit_Of_Measure=null;
			}
		}
	}
}

