for each  req_det in input.Material_Request_Details
{
	if(req_det.Item == null || req_det.Unit_Of_Measure == null)
	{
		req_det.Quantity_Issued_in_Base_Unit_Of_Measure=null;
		continue;
	}
	if(req_det.Quantity_Issued == null || req_det.Quantity_Issued < 0)
	{
		req_det.Quantity_Issued_in_Base_Unit_Of_Measure=null;
		continue;
	}
	check = store_management.po.check_uom_conversion_from_masaka_site_management(req_det.Item,req_det.Unit_Of_Measure);
	if(check == null || check.get("ok") != true)
	{
		alert ifnull(check.get("message"),"UOM conversion failed.");
		req_det.Quantity_Issued_in_Base_Unit_Of_Measure=null;
		continue;
	}
	issued_base_qty = store_management.po.convert_to_base_qty_from_masaka_site_management(req_det.Item,req_det.Unit_Of_Measure,req_det.Quantity_Issued);
	if(issued_base_qty != null && issued_base_qty >= 0)
	{
		req_det.Quantity_Issued_in_Base_Unit_Of_Measure=issued_base_qty;
	}
	else
	{
		req_det.Quantity_Issued_in_Base_Unit_Of_Measure=null;
	}
	if(req_det.Quantity != null && req_det.Quantity_Issued > req_det.Quantity)
	{
		alert "Quantity Issued cannot be greater than Quantity Requested.";
		req_det.Quantity_Issued=null;
		req_det.Quantity_Issued_in_Base_Unit_Of_Measure=null;
	}
}

for each  req_det in input.Material_Request_Details
{
	if(req_det.Item == null || req_det.Unit_Of_Measure == null)
	{
		req_det.Quantity_Returned_in_Base_Unit_Of_Measure=null;
		continue;
	}
	if(req_det.Quantity_Returned == null || req_det.Quantity_Returned < 0)
	{
		req_det.Quantity_Returned_in_Base_Unit_Of_Measure=null;
		continue;
	}
	check = store_management.po.check_uom_conversion_from_masaka_site_management(req_det.Item,req_det.Unit_Of_Measure);
	if(check == null || check.get("ok") != true)
	{
		alert ifnull(check.get("message"),"UOM conversion failed.");
		req_det.Quantity_Returned_in_Base_Unit_Of_Measure=null;
		continue;
	}
	returned_base_qty = store_management.po.convert_to_base_qty_from_masaka_site_management(req_det.Item,req_det.Unit_Of_Measure,req_det.Quantity_Returned);
	if(returned_base_qty != null && returned_base_qty >= 0)
	{
		req_det.Quantity_Returned_in_Base_Unit_Of_Measure=returned_base_qty;
	}
