	service_total = service_total + ifnull(s.Quantity,0.0) * ifnull(s.Rate,0.0);
}
input.Sub_Total = round(booking_total + item_total + service_total,2);
booking_tax = 0.0;
if(input.Booking_Tax_Type != null && booking_total > 0)
{
	booking_tax = round(booking_total * ifnull(input.Booking_Tax_Type.Tax_Rate,0.0) / 100,2);
}
input.Booking_Tax_Amount = booking_tax;
input.Tax_Amount = round(item_tax + booking_tax,2);
if(input.Discount_Type == "Percentage")
{
	input.Discount_Amount = round(input.Sub_Total * ifnull(input.Discount_Percentage,0.0) / 100,2);
}
else if(input.Discount_Type != "Amount")
{
	input.Discount_Amount = 0.0;
}
input.Grand_Total = input.Sub_Total + input.Tax_Amount - ifnull(input.Discount_Amount,0.0);
if(input.Grand_Total < 0)
{
	input.Grand_Total = 0.0;
}
input.Balance_Due = input.Grand_Total - ifnull(input.Amount_Paid,0.0) - ifnull(input.Amount_Credited,0.0);
if(input.Balance_Due < 0)
{
	input.Balance_Due = 0.0;
}
if(input.Cancel_Voucher == true)
{
	input.Payment_Status = "Cancelled";
}
else if(input.Grand_Total <= 0)
{
	input.Payment_Status = "Unpaid";
}
else if(input.Balance_Due == 0)
{
	if(ifnull(input.Amount_Credited,0.0) > 0 && ifnull(input.Amount_Paid,0.0) == 0)
	{
		input.Payment_Status = "Credit";
	}
	else
	{
		input.Payment_Status = "Paid";
	}
}
else if(ifnull(input.Amount_Paid,0.0) > 0)
{
	input.Payment_Status = "Partially Paid";
}
else if(ifnull(input.Amount_Credited,0.0) > 0)
{
	input.Payment_Status = "Partially Credited";
}
else
{
	input.Payment_Status = "Unpaid";
}
disable Booking_Tax_Amount;

input.Current_Outstanding_Balance = ifnull(input.Outstanding_Balance,0.0);
credit_limit = ifnull(input.Credit_Limit,0.0);
outstanding = ifnull(input.Current_Outstanding_Balance,0.0);
input.Available_Credit = 0.0;
if(input.Credit_Allowed == true)
{
	input.Available_Credit = credit_limit - outstanding;
	if(input.Available_Credit < 0)
	{
		input.Available_Credit = 0.0;
	}
	if(credit_limit <= 0)
	{
		input.Credit_Status = "On Hold";
	}
	else if(outstanding > credit_limit)
	{
		input.Credit_Status = "Over Limit";
	}
	else if(outstanding == credit_limit)
	{
		input.Credit_Status = "Limit Reached";
	}
	else
	{
		input.Credit_Status = "Good Standing";
	}
	show Credit_Limit;
	show Credit_Days_Allowed;
}
else
{
	input.Credit_Status = "None";
	hide Credit_Limit;
	hide Credit_Days_Allowed;
}
