// Protect billing while allowing deletion of unbilled or unpaid Draft vouchers.
source_forms = {"Freedom City Arena Management - Voucher Register","Freedom City Arena Management - Monthly Employee Days"};
voucher_number = ifnull(input.Voucher_Number,"");
protected_bill_ids = List();
for each  line in Bill_Details[Source_Form == "Freedom City Arena Management - Voucher Register" || Source_Form == "Freedom City Arena Management - Monthly Employee Days"]
{
	matches = line.Source_Record_ID == input.ID;
	if(voucher_number != "" && ifnull(line.Reference,"").contains(voucher_number) || ifnull(line.Details,"").contains(voucher_number))
	{
		matches = true;
	}
	if(matches)
	{
		if(ifnull(line.Bill_Details_Status,"Draft") != "Draft" && line.Bill_Details_Status != "Cancelled")
		{
			alert "This voucher has finalized Bill Details. Reverse or reopen that billing before deleting the voucher.";
			cancel delete;
		}
		if(line.Bill != null && !protected_bill_ids.contains(line.Bill))
		{
			protected_bill_ids.add(line.Bill);
		}
	}
}
for each  bill_id in protected_bill_ids
{
	b = Bill[ID == bill_id];
	if(b.ID != null)
	{
		if(ifnull(b.Bill_Status,"Draft") != "Draft" || ifnull(b.Amount_Paid,0) > 0)
		{
			alert "This voucher contributes to a paid or finalized Bill. Reverse or reopen that billing before deleting the voucher.";
			cancel delete;
		}
		for each  payment in Payment_Made_Voucher[ID != null]
		{
			for each  allocation in payment.Made_Details
			{
				if(allocation.Bill == bill_id && ifnull(allocation.Amount_Allocated,0) > 0)
				{
					alert "This voucher's Bill has payment allocations. Remove or reverse those payments before deleting the voucher.";
					cancel delete;
				}
			}
		}
	}
}
if(Sales_Voucher[Voucher == input.ID].count() > 0)
{
	alert "This voucher still has linked Sales Vouchers. Resolve those sales before deleting it.";
	cancel delete;
}

// Only voucher-generated billing is affected; manual and unassigned manual details remain.
voucher_number = ifnull(input.Voucher_Number,"");
affected_ids = List();
affected_bills = List();
monthly_bills = List();
synced_vouchers = List();
for each  line in Bill_Details[Source_Form == "Freedom City Arena Management - Voucher Register" || Source_Form == "Freedom City Arena Management - Monthly Employee Days"]
{
	matches = line.Source_Record_ID == input.ID;
	if(voucher_number != "" && ifnull(line.Reference,"").contains(voucher_number) || ifnull(line.Details,"").contains(voucher_number))
	{
		matches = true;
	}
	if(matches)
	{
		affected_ids.add(line.ID);
		if(line.Bill != null && !affected_bills.contains(line.Bill))
		{
			affected_bills.add(line.Bill);
		}
	}
}
for each  detail_id in affected_ids
{
	line = Bill_Details[ID == detail_id];
	if(line.ID != null)
	{
		is_normal_monthly = false;
		if(line.Bill != null && line.Expense_Type == "Monthly Payment")
		{
			parent_bill = Bill[ID == line.Bill];
			if(parent_bill.Employee_Vendor != null)
			{
				employee_number = ifnull(parent_bill.Employee_Vendor.Employee_Number,0);
				if(employee_number < 10000 || employee_number > 20000)
				{
					is_normal_monthly = true;
				}
			}
		}
		if(is_normal_monthly)
		{
			if(!monthly_bills.contains(line.Bill))
			{
				monthly_bills.add(line.Bill);
			}
		}
		else
		{
			remaining_id = 0;
			line_day = line.Details_Date;
			if(line_day != null)
			{
				day_end = line_day.addDay(1);
				if(ifnull(line.Details,"").contains("Employees / Vouchers:"))
				{
					for each  remaining in Voucher_Register[Display_Name_Site == line.Current_Site && Date_Time_In >= line_day && Date_Time_In < day_end && Cancel_Voucher != true]
					{
						if(remaining.Employee != null)
						{
							employee_number = ifnull(remaining.Employee.Employee_Number,0);
							if(employee_number >= 10000 && employee_number <= 20000)
							{
								remaining_id = remaining.ID;
							}
						}
					}
				}
				else if(ifnull(line.Details,"").contains("Allowance Type: Weekly Allowance") && line.Bill != null)
				{
					parent_bill = Bill[ID == line.Bill];
					period_end = parent_bill.Bill_Date;
					period_start = period_end.addDay(-7);
					for each  remaining in Voucher_Register[Employee == input.Employee && Date_Time_In >= period_start && Date_Time_In < period_end && Cancel_Voucher != true]
					{
						remaining_id = remaining.ID;
					}
				}
				else
				{
					for each  remaining in Voucher_Register[Employee == input.Employee && Date_Time_In >= line_day && Date_Time_In < day_end && Cancel_Voucher != true]
					{
						remaining_id = remaining.ID;
					}
				}
			}
			if(remaining_id > 0)
			{
				if(!synced_vouchers.contains(remaining_id))
				{
					response = thisapp.billing.syncEmployeeBilling(remaining_id);
					synced_vouchers.add(remaining_id);
				}
			}
			else
			{
				delete from Bill_Details[ID == detail_id];
			}
		}
	}
}
// Monthly salary must preserve approved paid leave as well as remaining vouchers.
for each  bill_id in monthly_bills
{
	thisapp.billing.syncMonthlyEmployeeDays(bill_id);
	for each  detail_id in affected_ids
	{
		line = Bill_Details[ID == detail_id && Bill == bill_id];
		if(line.ID != null)
		{
			if(ifnull(line.Quantity,0) <= 0)
			{
				delete from Bill_Details[ID == detail_id];
			}
			else
			{
				parent_bill = Bill[ID == bill_id];
				source_id = 0;
				day_end = line.Details_Date.addDay(1);
				for each  remaining in Voucher_Register[Employee == parent_bill.Employee_Vendor && Date_Time_In >= line.Details_Date && Date_Time_In < day_end && Cancel_Voucher != true]
				{
					source_id = remaining.ID;
				}
				line.Source_Record_ID=source_id;
				if(source_id == 0)
				{
					line.Source_Form="Freedom City Arena Management - Monthly Employee Days";
				}
			}
		}
	}
}
// Preserve shared Bills and any manually entered details or services.
for each  bill_id in affected_bills
{
	parent_bill = Bill[ID == bill_id];
	if(parent_bill.ID != null)
	{
		service_count = 0;
		for each  service in parent_bill.Services
		{
			service_count = service_count + 1;
		}
		if(Bill_Details[Bill == bill_id].count() == 0 && service_count == 0 && parent_bill.Bill_Status == "Draft" && ifnull(parent_bill.Amount_Paid,0) == 0 && ifnull(parent_bill.Tax_Amount,0) == 0 && ifnull(parent_bill.Discount_Amount,0) == 0)
		{
			delete from Bill[ID == bill_id];
		}
		else
		{
			totals = thisapp.billing.recalculateBillTotals(bill_id);
		}
	}
}

if(input.Booking_End <= input.Booking_Start)
{
	alert "Booking End must be later than Booking Start.";
	cancel submit;
}
minutes = (input.Booking_End.toLong() - input.Booking_Start.toLong()) / 60000.0;
quarters = minutes / 15;
if(quarters != quarters.toLong())
{
	alert "Use 15-minute booking intervals.";
	cancel submit;
}
if(input.Organiser_Type == "Arena Organised")
{
	if(input.Pitch_Hire_Sales_Voucher != null)
	{
		alert "Arena organised tournaments reserve the pitch internally; leave Pitch Hire Sales Voucher empty.";
		cancel submit;
	}
	if(input.Maximum_Teams == null || input.Maximum_Teams <= 0 || input.Entry_Fee == null || input.Entry_Fee <= 0)
	{
		alert "Enter a positive Maximum Teams and Entry Fee.";
		cancel submit;
	}
}
else
{
	input.Entry_Fee = 0;
	if(input.Customer == null)
	{
		alert "Choose the outside organiser's Customer.";
		cancel submit;
	}
	if(input.Tournament_Status == "Open" && input.Pitch_Hire_Sales_Voucher == null)
	{
		alert "Link the organiser's Pitch Hire Sales Voucher before opening the tournament.";
		cancel submit;
	}
	if(input.Pitch_Hire_Sales_Voucher != null)
	{
		hire = Sales_Voucher[ID == input.Pitch_Hire_Sales_Voucher];
		if(hire.Customer != input.Customer || hire.Sales_Type != "Single Booking" && hire.Sales_Type != "Single Booking + Item Sales" && hire.Sales_Type != "Tournament" || hire.Booking_Mode != "Exclusive" || hire.Item == null)
		{
			alert "The linked voucher must be an exclusive pitch-hire booking for this customer.";
			cancel submit;
		}
		if(hire.Booking_Start != input.Booking_Start || hire.Booking_End != input.Booking_End || hire.Booking_Area != input.Booking_Area)
		{
			alert "Tournament dates and area must match the linked Pitch Hire voucher.";
			cancel submit;
		}
		if(input.Tournament_Status == "Open" && hire.Cancel_Voucher == true)
		{
			alert "The linked Pitch Hire voucher is cancelled.";
			cancel submit;
		}
		if(input.Tournament_Status == "Cancelled" && hire.Cancel_Voucher != true)
		{
			alert "Cancel the linked Sales Voucher first, then cancel this tournament.";
			cancel submit;
		}
		for each  duplicate in Tournament_Register[Pitch_Hire_Sales_Voucher == input.Pitch_Hire_Sales_Voucher && ID != input.ID]
		{
			alert "This Pitch Hire Sales Voucher is already linked to another tournament.";
			cancel submit;
		}
	}
}
if(input.Tournament_Status == "Open")
{
	for each  other in Tournament_Register[ID != input.ID && Tournament_Status == "Open" && Organiser_Type == "Arena Organised" && Booking_Start < input.Booking_End && Booking_End > input.Booking_Start]
	{
		if(other.Booking_Area == input.Booking_Area || other.Booking_Area == "Whole Pitch" || input.Booking_Area == "Whole Pitch")
		{
			alert "This pitch area is reserved by " + other.Tournament_Title + ".";
			cancel submit;
		}
	}
	for each  reservation in Booking_Register[Booking_Start < input.Booking_End && Booking_End > input.Booking_Start && Booking_Status != "Cancelled"]
	{
		if(reservation.Sales_Voucher != null && reservation.Sales_Voucher != input.Pitch_Hire_Sales_Voucher)
		{
			otherSale = Sales_Voucher[ID == reservation.Sales_Voucher];
			if(otherSale.ID != null && otherSale.Cancel_Voucher != true && otherSale.Item != null)
			{
				otherArea = ifnull(otherSale.Booking_Area,"Whole Pitch");
				if(otherArea == input.Booking_Area || otherArea == "Whole Pitch" || input.Booking_Area == "Whole Pitch")
				{
					alert "This pitch area already has a Sales Voucher reservation.";
					cancel submit;
				}
			}
		}
	}
}
registered_count = Sales_Voucher[Tournament == input.ID && Cancel_Voucher != true].count();
if(input.ID != null)
{
	previous = Tournament_Register[ID == input.ID];
	all_registrations = Sales_Voucher[Tournament == input.ID].count();
	if(all_registrations > 0 && previous.Organiser_Type != input.Organiser_Type)
	{
		alert "The organiser type cannot change after Sales Vouchers have been linked.";
		cancel submit;
	}
	if(input.Organiser_Type == "Arena Organised")
	{
		if(input.Maximum_Teams < registered_count)
		{
			alert "Maximum Teams cannot be less than the number of active registered teams: " + registered_count;
			cancel submit;
		}
		if(all_registrations > 0 && input.Entry_Fee != previous.Entry_Fee)
		{
			alert "The entry fee cannot change after team Sales Vouchers have been recorded.";
			cancel submit;
		}
	}
}
if(input.Pitch_Hire_Sales_Voucher != null)
