	{
		input.Sales_Type = "Tournament";
		input.Item = null;
		input.Line_Total = 0;
		input.Booking_Tax_Amount = 0;
		hide Membership_Section;
		hide Membership_Details;
		show Product_Service_Details;
		show Product_Details;
