hide plain;
if(input.Organiser_Type == "Arena Organised")
{
	hide Customer;
	hide Pitch_Hire_Sales_Voucher;
	show Maximum_Teams;
	show Entry_Fee;
}
else if(input.Organiser_Type == "Externally Organised")
{
	show Customer;
	show Pitch_Hire_Sales_Voucher;
	hide Maximum_Teams;
	hide Entry_Fee;
}
if(input.Organiser_Type == "Arena Organised")
{
	if(input.Entry_Fee == null || input.Entry_Fee <= 0)
	{
		input.Entry_Fee = 300000;
	}
	if(input.Maximum_Teams == null || input.Maximum_Teams <= 0)
	{
		input.Maximum_Teams = 8;
	}
}

if(Sales_Voucher[Tournament == input.ID].count() > 0 || input.Pitch_Hire_Sales_Voucher != null)
{
	alert "This tournament has linked Sales Vouchers. Use Cancelled to release the booking and preserve sales/payment history.";
	cancel delete;
}
key = "Tournament_" + input.ID;
for each  reservation in Booking_Register[Session_Key == key]
{
	reservation.Booking_Status="Cancelled";
}

// Tournament keeps its own Sales Type while reusing the existing charge rules.
effective_sales_type = input.Sales_Type;
if(input.Sales_Type == "Tournament" && input.Tournament != null)
{
	if(input.Tournament.Organiser_Type == "Arena Organised")
	{
		effective_sales_type = "Item Sales";
	}
	else
	{
		effective_sales_type = "Single Booking";
		if(input.Product_Details.count() > 0)
		{
			effective_sales_type = "Single Booking + Item Sales";
		}
	}
}
if(input.Booking_Mode == "Shared Session" && input.Item != null)
{
	input.Session_Capacity = input.Item.Session_Capacity;
	if(input.Number_Of_Participants == null || input.Number_Of_Participants <= 0 || input.Number_Of_Participants > ifnull(input.Session_Capacity,0))
	{
		alert "Enter between 1 and " + ifnull(input.Session_Capacity,0) + " participants. The booking cannot be saved above capacity.";
	}
}
// Count sessions from the inclusive membership period.
input.Number_Of_Sessions = 0;
member_mode = effective_sales_type == "Membership Booking" || effective_sales_type == "Membership Booking + Item Sales";
booking_mode = member_mode || effective_sales_type == "Single Booking" || effective_sales_type == "Single Booking + Item Sales";
if(booking_mode && member_mode == false)
{
	input.Number_Of_Sessions = 1;
}
if(member_mode && input.Membership_Start_Date != null && input.Membership_End_Date != null && input.Repeat_Frequency != null)
{
	if(input.Membership_End_Date >= input.Membership_Start_Date)
	{
		days_count = input.Membership_Start_Date.daysBetween(input.Membership_End_Date) + 1;
		date_steps = "x".leftpad(days_count.toLong()).replaceAll(" ","x,").toList();
		session_count = 0;
		for each index day_index in date_steps
		{
			session_day = input.Membership_Start_Date.addDay(day_index);
			matches_day = false;
			if(input.Repeat_Frequency == "Daily")
			{
				matches_day = true;
			}
			else if(input.Repeat_Frequency == "Weekly" && input.Repeat_Days != null)
			{
				weekday_names = {"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};
				weekday_name = weekday_names.get(session_day.getDayOfWeek() - 1);
				matches_day = input.Repeat_Days.contains(weekday_name);
			}
			else if(input.Repeat_Frequency == "Monthly" && input.Day_Of_Month != null)
			{
				matches_day = session_day.getDay() == input.Day_Of_Month;
			}
			if(matches_day)
			{
				session_count = session_count + 1;
			}
		}
		input.Number_Of_Sessions = session_count;
	}
}
if(booking_mode)
{
	booking_participants = 1;
	if(input.Booking_Mode == "Shared Session")
	{
		booking_participants = ifnull(input.Number_Of_Participants,1);
	}
	booking_charge_units = ifnull(input.Quantity,0.0);
	if(input.Unit_Of_Measure != null && input.Unit_Of_Measure.Display_Name_Alternate_Unit_Of_Measure == "Player per Session")
	{
		booking_charge_units = 1;
	}
	input.Line_Total = round(booking_charge_units * ifnull(input.Unit_Price,0.0) * ifnull(input.Number_Of_Sessions,0) * booking_participants,2);
}
// Include the main booking once, additional items, and outsourced services.
legacy_booking = input.ID != null && input.Item == null && input.Product_Details.count() > 0;
booking_total = 0.0;
if(effective_sales_type == "Single Booking" || effective_sales_type == "Single Booking + Item Sales" || effective_sales_type == "Membership Booking" || effective_sales_type == "Membership Booking + Item Sales")
{
	booking_total = ifnull(input.Line_Total,0.0);
}
item_total = 0.0;
item_tax = 0.0;
if(legacy_booking || effective_sales_type == "Item Sales" || effective_sales_type == "Single Booking + Item Sales" || effective_sales_type == "Membership Booking + Item Sales")
{
	for each  r in input.Product_Details
	{
		item_total = item_total + ifnull(r.Line_Total,0.0);
		item_tax = item_tax + ifnull(r.Tax_Amount,0.0);
	}
}
service_total = 0.0;
for each  s in input.Services
{
	service_total = service_total + ifnull(s.Quantity,0.0) * ifnull(s.Rate,0.0);
}
input.Sub_Total = round(booking_total + item_total + service_total,2);
input.Booking_Tax_Amount = 0.0;
if(input.Booking_Tax_Type != null && booking_total > 0)
{
	input.Booking_Tax_Amount = round(booking_total * ifnull(input.Booking_Tax_Type.Tax_Rate,0.0) / 100,2);
}
input.Tax_Amount = round(item_tax + input.Booking_Tax_Amount,2);
if(input.Discount_Type == "Percentage")
{
	input.Discount_Amount = round(input.Sub_Total * ifnull(input.Discount_Percentage,0.0) / 100,2);
}
else if(input.Discount_Type != "Amount")
{
	input.Discount_Amount = 0.0;
}
input.Grand_Total = input.Sub_Total + input.Tax_Amount - ifnull(input.Discount_Amount,0.0);
if(input.Grand_Total < 0)
{
	input.Grand_Total = 0.0;
}
input.Balance_Due = input.Grand_Total - ifnull(input.Amount_Paid,0.0) - ifnull(input.Amount_Credited,0.0);
if(input.Balance_Due < 0)
{
	input.Balance_Due = 0.0;
}
if(input.Cancel_Voucher == true)
{
	input.Payment_Status = "Cancelled";
}
else if(input.Grand_Total <= 0)
{
	input.Payment_Status = "Unpaid";
}
else if(input.Balance_Due == 0)
{
	if(ifnull(input.Amount_Credited,0.0) > 0 && ifnull(input.Amount_Paid,0.0) == 0)
	{
		input.Payment_Status = "Credit";
	}
	else
	{
		input.Payment_Status = "Paid";
	}
}
else if(ifnull(input.Amount_Paid,0.0) > 0)
{
	input.Payment_Status = "Partially Paid";
}
else if(ifnull(input.Amount_Credited,0.0) > 0)
{
	input.Payment_Status = "Partially Credited";
}
else
{
	input.Payment_Status = "Unpaid";
}

