					bd.Rate=ifnull(row.Rate,0.0);
					bd.Account=account_text;
					bd.Current_Site=current_site_text;
					break;
				}
			}
			else
			{
				insert into Bill_Details
				[
					Line_Number=row.Line_Number
					Reference=reference_text
					Details_Date=zoho.currentdate
					Display_Name_Item=ifnull(row.Display_Name_Labour,"")
					Details=ifnull(row.Description,"")
					Quantity=ifnull(row.Quantity,0.0)
					Rate=ifnull(row.Rate,0.0)
					Account=account_text
					Current_Site=current_site_text
					Source_Record_ID=input.ID
					Source_Form=source_form
					Bill_Details_Status="Draft"
					Added_User=zoho.loginuser
				]
			}
			row.Status="Billed";
		}
	}
